UR='Usage Restriction'
B=[]
def show(name,cat,page,size,printed,rows,note=''):
    bp=sum(r[2] for r in rows); c=cr_of(size,bp)
    gap=''
    if isinstance(printed,int):
        r=[x for x in range(-600,6000) if cr_of(size,x)==printed]
        lo,hi=r[0],r[-1]
        gap='OK' if lo<=bp<=hi else (f"+{lo-bp}" if bp<lo else f"-{bp-hi}")
    B.append((name,cat,page,size,bp,c,printed,gap,note,rows))
def grav(scale,m,melee=False):
    # Ruling 2026-10-06: Gravitic = Energy cost + 5 (every hit applies [Flattened], priced as a standard Tag); Area required; no Coordinated Fire.
    base=[10,20,40][SC[scale]]; up=5*(m-2)*(m-1); c=base+up
    if melee: c//=2
    c+=5
    return other('Attack',f"Gravitic{' Melee' if melee else ''} ({scale}) {m}x (+5 [Flattened])",c,A('Attack',SN[scale],1,'gravitic',multiplier=m))
def plasma_free(scale,m): return counter('Shields',True)
def flightpack(): return drive('Minor','Reaction')
def arboreal(): return other('Drive','Minor Arboreal',10,A('Drive',1,1,'arboreal'))
def anomalous(): return other('Power Supply','Minor Anomalous rank 1',5,A('Power Supply',1,1,'anomalous'))
def portal(): return other('Hyperspace Portal','Major (priced as a Major Hangar, like the Deployment Pod\'s teleport platform)',60,A('Hangar',3,1,'hyperspacePortal'))
def fflink(): return other('Link','Major Force Field Link',50,A('Link',3,1,'forceField'))
def blades(): return other('Grav Blades','Major (replaces the Gravitic Drive), 1x',75,A('Grav Blades',3,1))
def jump(): return drive('Major','Jump')
# Ruling 2026-10-05: Pyre is its own Attack implementation (Battlefield only; relic). Cost = Battlefield Attack cost + 70:
# Counter: Armor 20, Force Field Overload 20, Aggravated Assault 30. Must carry [Time Heals No Wounds 3] (bought as a Tag).
def pyre(m):
    c=atk_cost('Battlefield',m,[])[0]+70
    return other('Attack',f"Pyre (Battlefield) {m}x: {c-70} + 70 (Counter: Armor, Force Field Overload, Aggravated Assault)",c,A('Attack',2,1,'pyre',multiplier=m))

